def transform(grid):
    cols=set()
    for r in grid:
        for j,x in enumerate(r):
            if x!=0: cols.add(j)
    return [[0]*len(cols)]

def transform(grid):
    best=0
    for row in grid:
        cur=0
        for x in row:
            if x!=0:
                cur+=1
                best=max(best,cur)
            else:
                cur=0
    return [[0]*best]
